const sessionTurnHasUnsettledWork = `-- name: SessionTurnHasUnsettledWork :one
SELECT EXISTS(SELECT 1 FROM session_messages m WHERE m.session_id=$1 AND m.turn_id=$2 AND m.status IN ('accepted','handling','unknown'))
 OR EXISTS(SELECT 1 FROM run_waits WHERE run_waits.turn_session_id=$1 AND run_waits.turn_id=$2
  AND (suspension_status NOT IN ('released','cancelled','failed')
   OR (child_run_id IS NOT NULL AND EXISTS(SELECT 1 FROM runs c WHERE c.id=run_waits.child_run_id AND c.status NOT IN ('succeeded','failed','cancelled','expired','system_failed'))))) AS unsettled
`

type SessionTurnHasUnsettledWorkParams struct {
	SessionID pgtype.UUID `json:"session_id"`
	TurnID    pgtype.UUID `json:"turn_id"`
}

func (q *Queries) SessionTurnHasUnsettledWork(ctx context.Context, arg SessionTurnHasUnsettledWorkParams) (pgtype.Bool, error) {
	row := q.db.QueryRow(ctx, sessionTurnHasUnsettledWork, arg.SessionID, arg.TurnID)
	var unsettled pgtype.Bool
	err := row.Scan(&unsettled)
	return unsettled, err
}

const sessionTurnMessageReady = `-- name: SessionTurnMessageReady :one
SELECT EXISTS (
 SELECT 1 FROM session_turns t
 JOIN sessions s ON s.id=t.session_id AND s.active_turn_id=t.id AND s.current_run_id=t.run_id AND s.run_generation=t.run_generation
 JOIN runs r ON r.id=t.run_id AND r.current_attempt_number=t.attempt_number
 JOIN run_leases l ON l.id=t.ready_run_lease_id AND l.id=r.current_run_lease_id AND l.run_id=r.id AND l.attempt_number=t.attempt_number
 JOIN worker_instances w ON w.id=l.worker_instance_id AND w.current_epoch=l.worker_epoch
 JOIN runtime_instances ri ON ri.id=l.runtime_instance_id
 WHERE t.environment_id=$1 AND t.session_id=$2 AND t.id=$3
   AND s.status IN ('open','closing') AND s.dispatch_hold_id IS NULL
   AND t.status='running' AND t.interrupt_requested_at IS NULL AND t.settlement_started_at IS NULL
   AND r.status='running' AND l.status='running' AND l.expires_at > now()
   AND w.lost_at IS NULL AND w.termination_ready_at IS NULL
   AND ri.observed_state='ready' AND ri.reclaimed_at IS NULL
)::boolean AS ready
`

type SessionTurnMessageReadyParams struct {
	EnvironmentID pgtype.UUID `json:"environment_id"`
	SessionID     pgtype.UUID `json:"session_id"`
	ID            pgtype.UUID `json:"id"`
}

func (q *Queries) SessionTurnMessageReady(ctx context.Context, arg SessionTurnMessageReadyParams) (bool, error) {
	row := q.db.QueryRow(ctx, sessionTurnMessageReady, arg.EnvironmentID, arg.SessionID, arg.ID)
	var ready bool
	err := row.Scan(&ready)
	return ready, err
}

const sessionWriterExcluded = `-- name: SessionWriterExcluded :one
SELECT NOT EXISTS(SELECT 1 FROM workspace_leases WHERE workspace_leases.workspace_id=$1 AND status IN ('active','releasing'))
 AND NOT EXISTS(SELECT 1 FROM workspace_processes WHERE workspace_processes.workspace_id=$1 AND status IN ('pending','starting','running','exit_requested'))
 AND NOT EXISTS(SELECT 1 FROM runtime_instances WHERE runtime_instances.workspace_id=$1 AND reclaimed_at IS NULL)
 AND NOT EXISTS(SELECT 1 FROM run_waits w JOIN runs c ON c.id=w.child_run_id WHERE w.workspace_id=$1
  AND c.parent_owns_lifecycle AND c.status NOT IN ('succeeded','failed','cancelled','expired','system_failed')) AS excluded
`

func (q *Queries) SessionWriterExcluded(ctx context.Context, workspaceID pgtype.UUID) (pgtype.Bool, error) {
	row := q.db.QueryRow(ctx, sessionWriterExcluded, workspaceID)
	var excluded pgtype.Bool
	err := row.Scan(&excluded)
	return excluded, err
}

